import{_t as e,at as t,et as n,it as r,n as i,ot as a,rt as o,xt as s}from"./chunks/framework.C1oW5ckO.js";var c=JSON.parse(`{"title":"BedrockAddonManager","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/bedrock-addon-manager/docs/index.md"},"headers":[],"relativePath":"packages/bedrock-addon-manager/docs/index.md","filePath":"packages/bedrock-addon-manager/docs/index.md","lastUpdated":1792029819000}`),l={name:`packages/bedrock-addon-manager/docs/index.md`},u={id:`bedrockaddonmanager`,tabindex:`-1`,class:`component-page-title`},d={class:`component-page-title__version`};function f(i,c,l,f,p,m){let h=s(`Badge`);return e(),o(`div`,null,[n(`h1`,u,[c[0]||=n(`span`,{class:`component-page-title__text`},[t(`BedrockAddonManager `),n(`a`,{class:`header-anchor`,href:`#bedrockaddonmanager`,"aria-label":`Permalink to “BedrockAddonManager”`},`​`)],-1),n(`span`,d,[a(h,{type:`info`,text:`v0.0.0`})])]),c[1]||=r(`<p>BedrockAddonManager scans Bedrock <code>.mcpack</code> and <code>.mcaddon</code> files, reads pack manifests, and serves the selected resource packs over HTTP. Use it to host packs at URLs that Bedrock clients can reach.</p><p>BedrockAddonManager does not send resource-pack offers to players. Clients are not prompted to download packs, and <code>packs.force</code> has no effect.</p><h2 id="typical-setup" tabindex="-1">Typical setup <a class="header-anchor" href="#typical-setup" aria-label="Permalink to “Typical setup”">​</a></h2><p>Install <code>bedrock-addon-manager.wasm</code> in the server&#39;s <code>plugins/</code> directory and restart. Put pack files in <code>plugins/data/BedrockAddonManager/packs/</code>, then run <code>/baddon reload</code> or restart again. <code>/baddon list</code> shows each discovered pack and its effective settings. The plugin does not modify <code>pumpkin.toml</code>.</p><p>Choose a URL Bedrock clients can reach. Set <code>web.public_url</code> when serving packs through a known address or reverse proxy. If it is empty and the server binds to <code>0.0.0.0</code>, the plugin can ask UPnPumpkin to forward <code>web.port</code>; without a successful mapping it falls back to a loopback address, which only works on the server machine. See the setup and troubleshooting pages in this section for network and pack-format details.</p><h2 id="pack-selection" tabindex="-1">Pack selection <a class="header-anchor" href="#pack-selection" aria-label="Permalink to “Pack selection”">​</a></h2><p>The plugin reads each pack&#39;s <code>manifest.json</code> for its UUID, version, and flags. An <code>.mcaddon</code> may contain both behavior and resource packs; only its resource packs are extracted and served because Pumpkin cannot use behavior packs. Per-file overrides can disable a pack, set its order, or provide an external <code>download_url</code>. Overrides for extracted packs use the name shown by <code>/baddon list</code>.</p><p>The built-in server uses plain HTTP. Put a TLS reverse proxy in front of it when clients need an HTTPS URL, or host the files elsewhere and configure download URLs.</p>`,8)])}var p=i(l,[[`render`,f]]);export{c as __pageData,p as default};